[HtmlTargetElement("email", Attributes = "mail-to")]
public class EmailTagHelper : TagHelper
{
    public string MailTo { get; set; }
    public string Content { get; set; } = "Contact us";

    public override void Process(TagHelperContext context, TagHelperOutput output)
    {
        output.TagName = "a";
        output.Attributes.SetAttribute("href", $"mailto:{MailTo}");
        output.Content.SetContent(Content);
    }
}

<!-- Usage in Razor -->
<email mail-to="support@example.com" content="Email Support"></email>
<!-- Renders: <a href="mailto:support@example.com">Email Support</a> -->
